export function formAttributeValueTypeDefault({ yaml, operation }: {
  readonly yaml?: unknown
  readonly operation: string
}): { type: [] } | undefined {
  if (operation !== "importFromYAML" || yaml === null || typeof yaml !== "object" || Array.isArray(yaml)) return undefined
  const item = yaml as Record<string, unknown>
  const facts = preparedXMLDependencyFacts(yaml)
  const type = facts === undefined ? item.Тип : facts.item.Тип
  if (
    type === "СписокЗначений" &&
    !Object.prototype.hasOwnProperty.call(item, "ТипЗначения")
  ) {
    return { type: [] }
  }
  return undefined
}

({
    context,
    name,
    operation,
  }: {
    context: {
      languages: { readonly default: string }
    }
    name?: string
    operation: string
  }) => {
    if (operation === "importFromXML") {
      return {
        items: { [context.languages.default]: "" },
      }
    }
    if (name === undefined) throw new Error("name is required for title default value")
    return {
      items: { [context.languages.default]: splitPascalCase(name) },
    }
  }

